// 1. OpenTelemetry Batch Metrics Ingestion
POST /v1/metrics
Headers:
  Content-Encoding: zstd
  X-Scope-OrgID: tenant_prod_01
Request:
{
  "series": [
    {
      "metric": "http_request_duration_ms_p99",
      "labels": { "service": "checkout", "region": "us-east-1", "status": "200" },
      "samples": [
        { "timestamp_ms": 1790784600000, "value": 42.8 },
        { "timestamp_ms": 1790784610000, "value": 41.2 }
      ]
    }
  ]
}
Response (202 Accepted):
{
  "accepted_samples": 2,
  "rejected_high_cardinality": 0
}

// ---------------------------------------------------------------------------
// Core Storage Entities & Schema Definitions
// ---------------------------------------------------------------------------
ENTITY metric_series_index (TSDB Inverted Index (Roaring Bitmaps)) {
  [PK ] series_id              UINT64 (xxHash64)
  [IDX] metric_name            VARCHAR(128)
  [IDX] label_kv_pairs         JSONB / PostingList
        tenant_id              VARCHAR(64)
        created_epoch          BIGINT
}

ENTITY gorilla_ts_chunks (TSDB Hot Storage + S3 Parquet) {
  [PK ] series_id              UINT64 (Composite PK)
  [PK ] block_start_ms         INT64 (2-Hour Window)
        sample_count           INT
        xor_compressed_blob    BYTEA (1.37 B/sample)
}

ENTITY structured_log_chunks (ClickHouse / Loki Columnar Store) {
  [PK ] tenant_stream_id       UINT64
  [PK ] chunk_start_ns         INT64
  [IDX] trace_id_bloom         BLOOM_FILTER
        zstd_columnar_blob     BYTEA (10:1 Ratio)
}

// Relationships: metric_series_index --(1 : N (2-hour Gorilla blocks))--> gorilla_ts_chunks --(1 : N (correlated by trace_id))--> structured_log_chunks
